const days=(a,b)=>Math.max(0,Math.ceil((parse(b)-parse(a))/DAY)); const pct=(a,b)=>b?round(a/b*100,1):0; const key=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
