/* Aldus source: factory-jurisprudencia-prompt-v332.js */
(() => {
  "use strict";

  const SOURCE_FOLDER = "https://drive.google.com/drive/folders/1ECc_otgQKwH7WfPdQr8CtD0kB07pz9Xe";
  const MIGRATION_ID = "factoryJurisprudenciaFonteCoberturaV332";
  const BASE_PROMPT = String(defaultFactoryPromptLibrary?.jurisprudencia || "").trim();

  const OLD_SOURCE_BLOCK = `## ESCOPO DO MÓDULO

USE APENAS AS FONTES CLASSIFICADAS COMO JURISPRUDÊNCIA NA TRIAGEM.

RESPEITE A DISCIPLINA, O TEMA E O RECORTE TEMÁTICO INFORMADOS.

SE O RECORTE TEMÁTICO ESTIVER AUSENTE OU IMPRECISO, INTERROMPA A GERAÇÃO E SOLICITE CONFIRMAÇÃO.

TRIBUNAL E PERÍODO SOMENTE DEVEM SER LIMITADOS QUANDO EXPRESSAMENTE INDICADOS.

NÃO GERAR MÓDULO RESUMO/AULA, LEI, PEÇA OU CONSOLIDAÇÃO FINAL.

NÃO INSERIR PCDF, BANCA, CONCURSO, PROFESSORA, CURSO OU TURMA.

## VALIDAÇÃO OBRIGATÓRIA DAS FONTES

ANTES DE AFIRMAR QUE NÃO EXISTE JURISPRUDÊNCIA:

1. RECUPERE INTEGRALMENTE O RESULTADO DA TRIAGEM.
2. IDENTIFIQUE TODAS AS FONTES CLASSIFICADAS COMO JURISPRUDÊNCIA.
3. ABRA E EXAMINE INDIVIDUALMENTE CADA FONTE APROVADA.
4. PROCURE JULGADOS, SÚMULAS, TEMAS, REPETITIVOS, INFORMATIVOS E TESES NO CONTEÚDO, E NÃO APENAS NO NOME DO ARQUIVO.
5. NÃO CONFUNDA AUSÊNCIA DE INFORMATIVO, SÚMULA OU TEMA NUMERADO COM AUSÊNCIA DE JURISPRUDÊNCIA.
6. NÃO CONCLUA PELA INEXISTÊNCIA COM BASE EM LEITURA PARCIAL, RESULTADO VAZIO INICIAL, FALHA DE INDEXAÇÃO OU FALHA DE ACESSO.
7. REEXAMINE AS FONTES UMA SEGUNDA VEZ QUANDO A TRIAGEM INDICAR EXISTÊNCIA, SUFICIÊNCIA OU CONTEÚDO JURISPRUDENCIAL.

SE A TRIAGEM NÃO PUDER SER RECUPERADA, INFORME:
“NÃO FOI POSSÍVEL RECUPERAR A CLASSIFICAÇÃO DA TRIAGEM.”

SE ALGUMA FONTE APROVADA ESTIVER INACESSÍVEL, INFORME:
“A EXISTÊNCIA DE JURISPRUDÊNCIA NÃO PÔDE SER VERIFICADA INTEGRALMENTE, POIS HÁ FONTES INACESSÍVEIS.”

SOMENTE DECLARE “NÃO HÁ JURISPRUDÊNCIA” DEPOIS DE EXAMINAR INTEGRALMENTE TODAS AS FONTES APROVADAS E CONFIRMAR QUE NENHUMA CONTÉM MATERIAL PERTINENTE AO RECORTE.

ANTES DESSA CONCLUSÃO NEGATIVA, REGISTRE INTERNAMENTE:
* QUANTIDADE DE FONTES CLASSIFICADAS COMO JURISPRUDÊNCIA;
* QUANTIDADE EFETIVAMENTE ABERTA E EXAMINADA;
* QUANTIDADE DE PRECEDENTES, SÚMULAS, TEMAS, REPETITIVOS, INFORMATIVOS OU TESES LOCALIZADOS.`;

  const NEW_SOURCE_BLOCK = `## ESCOPO DO MÓDULO

USE EXCLUSIVAMENTE A PASTA JURISPRUDENCIAL ${SOURCE_FOLDER} E TODAS AS SUAS SUBPASTAS.

NÃO CONDICIONE ESTA BUSCA À TRIAGEM DA PASTA GERAL E NÃO PESQUISE EM OUTRAS PASTAS, NA INTERNET OU NA MEMÓRIA DO MODELO.

RESPEITE A DISCIPLINA, O TEMA E O RECORTE TEMÁTICO INFORMADOS.

SE O RECORTE TEMÁTICO ESTIVER AUSENTE OU IMPRECISO, INTERROMPA A GERAÇÃO E SOLICITE CONFIRMAÇÃO.

TRIBUNAL E PERÍODO SOMENTE DEVEM SER LIMITADOS QUANDO EXPRESSAMENTE INDICADOS.

NÃO GERAR MÓDULO RESUMO/AULA, LEI, PEÇA OU CONSOLIDAÇÃO FINAL.

NÃO INSERIR PCDF, BANCA, CONCURSO, PROFESSORA, CURSO OU TURMA.

## VALIDAÇÃO OBRIGATÓRIA DAS FONTES

ANTES DE REDIGIR OU AFIRMAR QUE NÃO EXISTE JURISPRUDÊNCIA:

1. PERCORRA RECURSIVAMENTE A PASTA JURISPRUDENCIAL EXCLUSIVA E TODAS AS SUAS SUBPASTAS.
2. EXAMINE OBRIGATORIAMENTE, EM PRIMEIRO PLANO, AS SUBPASTAS “JULGADOS STF RESUMIDOS” E “JULGADOS STJ RESUMIDOS”.
3. FAÇA INVENTÁRIO INTERNO DOS ARQUIVOS POTENCIALMENTE RELACIONADOS À DISCIPLINA, AO TEMA E AO RECORTE.
4. PESQUISE O TEMA LITERAL E TAMBÉM SINÔNIMOS, SIGLAS, VARIAÇÕES TERMINOLÓGICAS E INSTITUTOS JURÍDICOS DIRETAMENTE CORRELATOS.
5. ABRA E EXAMINE INDIVIDUALMENTE O CONTEÚDO DE CADA ARQUIVO CANDIDATO; NÃO DECIDA APENAS PELO NOME DO ARQUIVO.
6. PROCURE JULGADOS, SÚMULAS, TEMAS, REPETITIVOS, INFORMATIVOS E TESES EM TODO O CONTEÚDO ACESSÍVEL.
7. INCLUA TODOS OS ITENS DIRETAMENTE PERTINENTES AO RECORTE, SEM LIMITE MÁXIMO ARBITRÁRIO E SEM REDUZIR A QUANTIDADE POR AMOSTRAGEM.
8. ELIMINE APENAS REPETIÇÕES DO MESMO PROCESSO, TEMA OU SÚMULA; NÃO ELIMINE DECISÕES DISTINTAS QUE ACRESCENTEM REGRA, CONDIÇÃO, EXCEÇÃO OU EVOLUÇÃO PRÓPRIA.
9. SE A QUANTIDADE LOCALIZADA PARECER INFERIOR AO CONTEÚDO DO ACERVO, REPITA A BUSCA COM AS VARIAÇÕES TERMINOLÓGICAS ANTES DE FINALIZAR.
10. NÃO CONFUNDA AUSÊNCIA DE INFORMATIVO, SÚMULA OU TEMA NUMERADO COM AUSÊNCIA DE JURISPRUDÊNCIA.

NÃO CONCLUA PELA INEXISTÊNCIA COM BASE EM LEITURA PARCIAL, RESULTADO VAZIO INICIAL, FALHA DE INDEXAÇÃO, PAGINAÇÃO INCOMPLETA OU FALHA DE ACESSO.

SE ALGUM ARQUIVO CANDIDATO ESTIVER INACESSÍVEL, INFORME:
“A EXISTÊNCIA DE JURISPRUDÊNCIA NÃO PÔDE SER VERIFICADA INTEGRALMENTE, POIS HÁ FONTES INACESSÍVEIS.”

SOMENTE DECLARE “NÃO HÁ JURISPRUDÊNCIA” DEPOIS DE CONCLUIR A BUSCA RECURSIVA, EXAMINAR AS DUAS SUBPASTAS PRIORITÁRIAS, ABRIR TODOS OS ARQUIVOS CANDIDATOS ACESSÍVEIS E REPETIR A BUSCA COM VARIAÇÕES DO TEMA.

ANTES DESSA CONCLUSÃO NEGATIVA, REGISTRE INTERNAMENTE:
* QUANTIDADE DE SUBPASTAS PERCORRIDAS;
* QUANTIDADE DE ARQUIVOS CANDIDATOS EFETIVAMENTE ABERTA E EXAMINADA;
* TERMOS E VARIAÇÕES UTILIZADOS;
* QUANTIDADE DE PRECEDENTES, SÚMULAS, TEMAS, REPETITIVOS, INFORMATIVOS OU TESES LOCALIZADOS.`;

  const OLD_FIDELITY_SOURCE = "USE SOMENTE O CONTEÚDO FORNECIDO PELO USUÁRIO E AS FONTES APROVADAS NA TRIAGEM.";
  const NEW_FIDELITY_SOURCE = `USE SOMENTE O CONTEÚDO EFETIVAMENTE LOCALIZADO NA PASTA JURISPRUDENCIAL EXCLUSIVA ${SOURCE_FOLDER} E EM SUAS SUBPASTAS.`;
  const OLD_REVIEW_SOURCE = "* TODAS AS FONTES APROVADAS NA TRIAGEM FORAM ABERTAS E EXAMINADAS?";
  const NEW_REVIEW_SOURCE = "* A PASTA JURISPRUDENCIAL EXCLUSIVA, AS SUBPASTAS “JULGADOS STF RESUMIDOS” E “JULGADOS STJ RESUMIDOS” E TODOS OS ARQUIVOS CANDIDATOS ACESSÍVEIS FORAM PERCORRIDOS E EXAMINADOS?";

  const PROMPT = BASE_PROMPT
    .replace(OLD_SOURCE_BLOCK, NEW_SOURCE_BLOCK)
    .replace(OLD_FIDELITY_SOURCE, NEW_FIDELITY_SOURCE)
    .replace(OLD_REVIEW_SOURCE, NEW_REVIEW_SOURCE);

  // Instalações mais novas já podem ter um prompt oficial posterior à V231. Nesse
  // caso a migração histórica deve preservar o texto atual e encerrar em silêncio,
  // em vez de registrar como erro uma condição esperada e segura.
  if (!BASE_PROMPT || !BASE_PROMPT.includes(OLD_SOURCE_BLOCK) || PROMPT === BASE_PROMPT) {
    return;
  }

  function isOfficialPreviousPrompt(value) {
    const text = String(value || "").trim();
    if (!text || text === FACTORY_LIBRARY_FALLBACK || text === BASE_PROMPT || text === PROMPT) return true;
    const isV231 = text.includes("TRANSFORME JURISPRUDÊNCIAS EM MAPA MENTAL HIERÁRQUICO DE PALAVRAS-CHAVE")
      && text.includes("## FORMATO OBRIGATÓRIO")
      && text.includes("## ENTREGA EM WORD");
    const isV331 = text.includes("## 2. BUSCA SEMÂNTICA OBRIGATÓRIA EM TRÊS PASSAGENS")
      && text.includes("## 9. FORMATAÇÃO WORD E PAGINAÇÃO");
    return isV231 || isV331;
  }

  function install() {
    if (typeof defaultFactoryPromptLibrary === "undefined" || typeof state === "undefined") return;

    defaultFactoryPromptLibrary.jurisprudencia = PROMPT;
    state.migrations = state.migrations || {};
    state.factoryPromptLibrary = state.factoryPromptLibrary || {};
    state.factoryPromptLibraryBackups = state.factoryPromptLibraryBackups || {};

    const current = String(state.factoryPromptLibrary.jurisprudencia || "").trim();
    if (isOfficialPreviousPrompt(current)) {
      if (current && current !== PROMPT && current !== FACTORY_LIBRARY_FALLBACK) {
        state.factoryPromptLibraryBackups.jurisprudenciaBeforeV332 = current;
      }
      state.factoryPromptLibrary.jurisprudencia = PROMPT;
    }

    state.migrations[MIGRATION_ID] = true;
    state.factoryPromptLibrary = normalizeFactoryPromptLibrary(state.factoryPromptLibrary);
    if (typeof saveData === "function") saveData();

    const previousPromptBase = factoryPromptBase;
    factoryPromptBase = function factoryPromptBaseV332(type) {
      if (type !== "jurisprudencia") return previousPromptBase(type);
      const text = String(state.factoryPromptLibrary?.jurisprudencia || "").trim();
      return text || PROMPT;
    };

    console.info("[Aldus Meta] Prompt topificado de jurisprudência V332 ativo.");
  }

  if (window.__aldusBootstrapReady) install();
  else window.addEventListener("aldus:bootstrap-ready", install, { once: true });
})();

/* Aldus source: central-goals-real-time-v124.js */
(() => {
  const PATCH_VERSION = "20260721-central-tempo-visibilidade-v125";

  function ensureCentralTimeVisibilityStyles() {
    if (document.getElementById("centralTimeVisibilityV125")) return;
    const style = document.createElement("style");
    style.id = "centralTimeVisibilityV125";
    style.textContent = `
      html[data-aldus-theme="premium-stable"] #view-central-metas .central-time-pie > div {
        background: #061d31 !important;
        border-color: #5fa8d8 !important;
        box-shadow: 0 10px 28px rgba(0, 5, 16, .38) !important;
      }
      html[data-aldus-theme="premium-stable"] #view-central-metas .central-time-pie strong {
        color: #ffffff !important;
        text-shadow: 0 1px 2px rgba(0, 0, 0, .35) !important;
      }
      html[data-aldus-theme="premium-stable"] #view-central-metas .central-time-pie span {
        color: #c9deed !important;
      }
      html[data-aldus-theme="premium-stable"] #view-central-metas .central-time-legend h4 {
        color: #ffffff !important;
      }
      html[data-aldus-theme="premium-stable"] #view-central-metas .central-time-legend-row {
        border-color: #4b89b8 !important;
        background: linear-gradient(145deg, #0b2d47, #071f34) !important;
        color: #ffffff !important;
        box-shadow: 0 7px 18px rgba(0, 7, 18, .22) !important;
      }
      html[data-aldus-theme="premium-stable"] #view-central-metas .central-time-legend-row span {
        color: #f6fbff !important;
        font-weight: 800 !important;
      }
      html[data-aldus-theme="premium-stable"] #view-central-metas .central-time-legend-row strong {
        padding: 5px 9px !important;
        border: 1px solid rgba(95, 168, 216, .42) !important;
        border-radius: 9px !important;
        background: rgba(56, 189, 248, .12) !important;
        color: #e8f7ff !important;
        font-weight: 900 !important;
        white-space: nowrap !important;
      }
      html[data-aldus-theme="premium-stable"] #view-central-metas .central-time-legend > .item-meta {
        color: #c6d9e7 !important;
      }
      @media (max-width: 760px) {
        html[data-aldus-theme="premium-stable"] #view-central-metas .central-time-legend-row strong {
          justify-self: start !important;
        }
      }
    `;
    document.head.appendChild(style);
  }

  ensureCentralTimeVisibilityStyles();

  const container = document.getElementById("centralGoalsCards");
  if (!container) return;

  function safeLogs() {
    try {
      return typeof centralTimeChartLogs === "function" ? centralTimeChartLogs() : [];
    } catch (error) {
      console.warn("[Central de Metas] Não foi possível consolidar o tempo real.", error);
      return [];
    }
  }

  function totalBetween(logs, start, end) {
    return logs.reduce((sum, log) => {
      const date = String(log?.date || "");
      if (!date || date < start || date > end) return sum;
      return sum + Math.max(0, Number(log?.minutes) || 0);
    }, 0);
  }

  function formatMinutes(minutes) {
    if (typeof formatHours === "function") return formatHours(minutes);
    const hours = Math.floor(minutes / 60);
    const rest = Math.round(minutes % 60);
    return hours ? `${hours}h${rest ? ` ${rest}min` : ""}` : `${rest} min`;
  }

  function findCard(title) {
    return [...container.querySelectorAll(".goal-central-card")].find(
      (card) => card.querySelector("h3")?.textContent.trim() === title
    );
  }

  function setMetric(card, key, label, minutes) {
    const grid = card?.querySelector(".card-meta-grid");
    if (!grid) return;
    let row = [...grid.querySelectorAll("span")].find(
      (span) => span.dataset.centralRealTime === key || span.textContent.trim().startsWith(`${label}:`)
    );
    if (!row) {
      row = document.createElement("span");
      grid.appendChild(row);
    }
    row.dataset.centralRealTime = key;
    row.dataset.centralRealTimeVersion = PATCH_VERSION;
    const nextText = `${label}: ${formatMinutes(minutes)}`;
    if (row.textContent !== nextText) row.textContent = nextText;
  }

  function updateCentralRealTimes() {
    if (!container.isConnected) return;
    const today = typeof todayISO === "function"
      ? todayISO()
      : new Date().toLocaleDateString("en-CA");
    const weekStartDate = typeof weekStart === "function" ? weekStart(today) : today;
    const weekEndDate = typeof addDays === "function" ? addDays(weekStartDate, 6) : today;
    const parsedToday = typeof parseDate === "function" ? parseDate(today) : new Date(`${today}T00:00:00`);
    const monthStartDate = `${today.slice(0, 7)}-01`;
    const monthEndDate = `${today.slice(0, 7)}-${String(new Date(parsedToday.getFullYear(), parsedToday.getMonth() + 1, 0).getDate()).padStart(2, "0")}`;
    const logs = safeLogs();

    setMetric(findCard("Hoje"), "day", "Horas já cumpridas", totalBetween(logs, today, today));
    setMetric(findCard("Esta semana"), "week", "Horas já cumpridas", totalBetween(logs, weekStartDate, weekEndDate));
    setMetric(findCard("Este mês"), "month", "Horas já cumpridas", totalBetween(logs, monthStartDate, monthEndDate));
  }

  let scheduled = false;
  function scheduleUpdate() {
    if (scheduled) return;
    scheduled = true;
    requestAnimationFrame(() => {
      scheduled = false;
      updateCentralRealTimes();
    });
  }

  const observer = new MutationObserver(scheduleUpdate);
  observer.observe(container, { childList: true, subtree: true, characterData: true });
  window.addEventListener("storage", scheduleUpdate);
  document.addEventListener("visibilitychange", () => {
    if (!document.hidden) scheduleUpdate();
  });
  scheduleUpdate();
})();

